    c = mix(c, mix(vec3(.55, .12, .10), lampCol(uP2.w) * 1.4, uP2.w), (1. - smoothstep(uP2.z * .8, uP2.z * 1.15, d2)) * .85);
    c += lampCol(uP2.w) * uP2.w * .75 * exp(-max(d2 - uP2.z * .6, 0.) / 140.);
