const rgb = (css) => { const m = /^#?([0-9a-f]{6})$/i.exec(css.trim()); if (!m) return null; const n = parseInt(m[1], 16); return [(n >> 16) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; };
