    this.comboT = 1.1;
    const pts = this.pointValue;
    this.score += pts;
    if (!K.calm) {
      this.pop.x = Math.max(this.pop.x, 0.35);
      this.pop.v = 19;
      this.rx.v += dx * 260;
      this.ry.v += dy * 260;
    }
