    if (!this.capsTex || this.capsDirty) { this.capsTex = updateCapsTexture(this.capsTex, [this.capText]); this.capsDirty = false; }
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.max(1, Math.round(this.cv.clientWidth * dpr));
    const h = Math.max(1, Math.round(this.cv.clientHeight * dpr));
